def sort_versions(self):
        """Sort entries by version.

        The order is typically descending, but package order functions can
        change this.
        """
        if self.sorted:
            return

        for orderer in (self.solver.package_orderers or []):
            entries = orderer.reorder(self.entries, key=lambda x: x.package)
            if entries is not None:
                self.entries = entries
                self.sorted = True

                if self.pr:
                    self.pr("sorted: %s packages: %s", self.package_name, repr(orderer))
                return

        # default ordering is version descending
        self.entries = sorted(self.entries, key=lambda x: x.version, reverse=True)
        self.sorted = True

        if self.pr:
            self.pr("sorted: %s packages: version descending", self.package_name)

def update_elements(dst_pyxb, src_pyxb, el_list):
    """Copy elements specified in ``el_list`` from ``src_pyxb`` to ``dst_pyxb``

    Only elements that are children of root are supported. See
    SYSMETA_ROOT_CHILD_LIST.

    If an element in ``el_list`` does not exist in ``src_pyxb``, it is removed from
    ``dst_pyxb``.

    """
    invalid_element_set = set(el_list) - set(SYSMETA_ROOT_CHILD_LIST)
    if invalid_element_set:
        raise ValueError(
            'Passed one or more invalid elements. invalid="{}"'.format(
                ', '.join(sorted(list(invalid_element_set)))
            )
        )
    for el_str in el_list:
        setattr(dst_pyxb, el_str, getattr(src_pyxb, el_str, None))

def multi_path_generator(pathnames):
    """
    yields (name,chunkgen) for all of the files found under the list
    of pathnames given. This is recursive, so directories will have
    their contents emitted. chunkgen is a function that can called and
    iterated over to obtain the contents of the file in multiple
    reads.
    """

    for pathname in pathnames:
        if isdir(pathname):
            for entry in directory_generator(pathname):
                yield entry
        else:
            yield pathname, file_chunk(pathname)

